请对以下 case 进行三维加权评分。

=== case_id ===
Case-30-pet-feeder-005

=== 用户原始指令 (query.txt) ===
帮我整个喂食器卡片,能看到出粮比例,点一下跳app里,显示已连接

=== TaskSpec 契约 (task.taskSpec.json) ===
{
  "userQuery": "帮我整个喂食器卡片,能看到出粮比例,点一下跳app里,显示已连接",
  "size": "2x4",
  "eventCandidates": [
    {
      "call": "clickToDeeplink",
      "args": {
        "bundleName": "",
        "abilityName": "",
        "uri": "petfeeder://settings"
      }
    }
  ],
  "dataModelSchema": {
    "device": {
      "name": {
        "type": "string",
        "description": "喂食器设备名称",
        "sampleValue": "智能喂食器"
      },
      "connectionText": {
        "type": "string",
        "description": "喂食器当前连接状态展示文本",
        "sampleValue": "已连接"
      },
      "feedRatio": {
        "type": "number",
        "description": "当前出粮比例数值，用于进度组件",
        "sampleValue": 68
      },
      "feedRatioTotal": {
        "type": "number",
        "description": "出粮比例总量基准",
        "sampleValue": 100
      },
      "feedRatioText": {
        "type": "string",
        "description": "当前出粮比例展示文本",
        "sampleValue": "68%"
      },
      "ratioLabel": {
        "type": "string",
        "description": "出粮比例指标标签",
        "sampleValue": "出粮比例"
      },
      "portionText": {
        "type": "string",
        "description": "当前每餐出粮配比展示文本",
        "sampleValue": "当前配比 40g/餐"
      },
      "nextFeedText": {
        "type": "string",
        "description": "下一次计划出粮时间展示文本",
        "sampleValue": "18:30 下次出粮"
      },
      "actionText": {
        "type": "string",
        "description": "打开喂食器应用入口的短标签",
        "sampleValue": "打开应用"
      }
    }
  },
  "assetCandidates": []
}

